L0043|     ["jev-checkup-history.json", "runs/run-1.json"],
L0044|   );
L0045|   const restored = join(root, "restored");
L0046|   await mkdir(restored);
L0047|   assert.ok(await loadHistoryBranch(cwd, "jev-checkup-history", restored));
L0048|   assert.equal(await readFile(join(restored, "run-1.json"), "utf8"), '{"run":{"id":"run-1"}}\n');
L0049|   await assert.rejects(loadHistoryBranch(cwd, "main", join(root, "unsafe")), /dedicated history/);
