P0001| import { appendFile, copyFile, mkdir, mkdtemp, access, rm } from "node:fs/promises";
P0002| import { tmpdir } from "node:os";
P0003| import { dirname, join, resolve } from "node:path";
P0004| import { pathToFileURL } from "node:url";
P0005| import type { runCli } from "../cli/index.js";
P0006| import { loadHistoryBranch, saveHistoryBranch } from "./history.js";
P0007| 
P0008| export interface ActionOptions {
P0009|   workspace: string;
P0010|   eventName?: string;
P0011|   paths?: string;
P0012|   config?: string;
P0013|   stateDir?: string;
P0014|   historyBranch?: string;
P0015|   issue?: string;
P0016|   repository?: string;
P0017|   summaryPath?: string;
P0018|   outputPath?: string;
P0019| }
P0020| export async function runAction(
P0021|   options: ActionOptions,
P0022|   dependencies: { cli?: typeof runCli; log?: (message: string) => void } = {},
P0023| ): Promise<number> {
P0024|   const log = dependencies.log ?? ((message) => process.stderr.write(`${message}\n`));
P0025|   if (options.eventName?.startsWith("pull_request")) {
P0026|     const message =
P0027|       "Skipped: pull request events are not scanned or published by the scheduled dashboard Action.\n";
P0028|     if (options.summaryPath) await appendFile(options.summaryPath, message);
P0029|     log(message.trim());
P0030|     return 0;
P0031|   }
P0032|   const cli = dependencies.cli ?? (await import("../cli/index.js")).runCli;
P0033|   const temporary = await mkdtemp(join(tmpdir(), "jev-action-"));
P0034|   const history = join(temporary, "history"),
P0035|     output = join(temporary, "run.json");
P0036|   try {
P0037|     const workspace = resolve(options.workspace);
P0038|     const state = resolve(workspace, options.stateDir || ".jev-checkup");
P0039|     if (/[\r\n]/.test(state)) throw new Error("Invalid state path");
P0040|     const branch = options.historyBranch ?? "jev-checkup-history";
P0041|     const head = branch ? await loadHistoryBranch(workspace, branch, history) : null;
P0042|     await mkdir(history, { recursive: true });
P0043|     const args = [
P0044|       "scan",
P0045|       ...(options.paths || ".")
P0046|         .split(/\r?\n/)
P0047|         .map((s) => s.trim())
P0048|         .filter(Boolean),
P0049|       "--state-dir",
P0050|       state,
P0051|       "--out",
P0052|       output,
P0053|       "--history",
P0054|       history,
P0055|     ];
P0056|     if (options.config) args.push("--config", options.config);
P0057|     const env = {
P0058|       cwd: workspace,
P0059|       stdout: (_value: string) => undefined,
P0060|       stderr: log,
P0061|       summaryPath: options.summaryPath,
P0062|     };
P0063|     const scanExit = await cli(args, env);
P0064|     try {
P0065|       await access(output);
P0066|     } catch {
P0067|       return scanExit || 2;
P0068|     }
P0069|     const saved = join(state, "run.json");
P0070|     await mkdir(dirname(saved), { recursive: true });
P0071|     await copyFile(output, saved);
P0072|     if (options.outputPath) await appendFile(options.outputPath, `run-json=${saved}\n`);
P0073|     const reportArgs = ["report", output, "--format", "github", "--history", history];
P0074|     if (options.issue) reportArgs.push("--issue", options.issue);
P0075|     if (options.repository) reportArgs.push("--repo", options.repository);
P0076|     const reportExit = await cli(reportArgs, env);
P0077|     if (branch) await saveHistoryBranch(workspace, branch, history, head);
P0078|     return scanExit || reportExit;
P0079|   } catch {
P0080|     log(
P0081|       "Dashboard action failed; inspect the CLI result and history branch permissions or concurrent updates.",
P0082|     );
P0083|     return 2;
P0084|   } finally {
P0085|     await rm(temporary, { recursive: true, force: true });
P0086|   }
P0087| }
P0088| 
P0089| if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
P0090|   process.exitCode = await runAction({
P0091|     workspace: process.env.GITHUB_WORKSPACE ?? process.cwd(),
P0092|     eventName: process.env.GITHUB_EVENT_NAME,
P0093|     paths: process.env.JEV_PATHS,
P0094|     config: process.env.JEV_CONFIG,
P0095|     stateDir: process.env.JEV_STATE_DIR,
P0096|     historyBranch: process.env.JEV_HISTORY_BRANCH,
P0097|     issue: process.env.JEV_ISSUE,
P0098|     repository: process.env.GITHUB_REPOSITORY,
P0099|     summaryPath: process.env.GITHUB_STEP_SUMMARY,
P0100|     outputPath: process.env.GITHUB_OUTPUT,
P0101|   });
P0102| }
