L0001| import test from "node:test";
L0002| import assert from "node:assert/strict";
L0003| import { mkdtemp, rm, writeFile, readFile, readdir, access } from "node:fs/promises";
L0004| import { tmpdir } from "node:os";
L0005| import { join } from "node:path";
L0006| import { runCli } from "../src/cli/index.js";
L0007| import { readRun, writeRun } from "../src/cli/storage.js";
L0008| import type { Answers, Questions } from "../src/types.js";
L0009| import type { JudgeClient } from "../src/observe/index.js";
L0010| 
L0011| function answers(questions: Questions, finding: boolean): Answers {
L0012|   return Object.fromEntries(Object.entries(questions).map(([id, question]) => {
L0013|     const property = id.split("__").at(-1)!;
L0014|     if (question.type === "noul") return [id, { type: "noul", noul: property === "ctl_own_snippet" ? 1 : property === "outcome_unasserted" && finding ? 0.9 : 0 }];
L0015|     if (question.type === "score") return [id, { type: "score", score: 0, confidence: 1, probabilities: { "0": 1, "1": 0, "2": 0 }, legend: { "0": "Exact asserted result", "1": "Partial shape", "2": "Existence only" } }];
L0016|     const criteria = question.criteria as Record<string, unknown>;
L0017|     const choice = "verifies" in criteria ? "verifies" : Object.keys(criteria)[0]!;
L0018|     return [id, { type: "choice", choice, confidence: 1, probabilities: Object.fromEntries(Object.keys(criteria).map(key => [key, key === choice ? 1 : 0])) }];
L0019|   }));
L0020| }
