P0516| function requestFailureReason(error: unknown): RequestFailureReason {
P0517|   const status = errorStatus(error);
P0518|   if (status === 401 || status === 403) return "auth_failed";
P0519|   if (status === 429) return "rate_limited";
P0520|   if (status !== undefined && status >= 500 && status <= 599) return "server_error";
