P0686| /**
P0687|  * Execute only the missing questions in a plan, bounded by concurrency and
P0688|  * request/token start rates.  Every failed item becomes an incomplete
P0689|  * observation so one API failure cannot discard the rest of the scan.
P0690|  */
P0691| export async function observe(
P0692|   plan: Plan,
P0693|   definition: AspectDefinition,
P0694|   options: ObserveOptions,
P0695| ): Promise<ObserveResult> {
P0696|   const usage: Usage = { requests: 0, inputTokens: 0, cacheHits: 0 };
P0697|   const authStopController = new AbortController();
P0698|   const onExternalAbort = () => authStopController.abort();
P0699|   options.signal?.addEventListener("abort", onExternalAbort, { once: true });
P0700|   if (options.signal?.aborted) authStopController.abort();
P0701|   const limiter = new StartRateLimiter(
P0702|     requestRateInterval(options.requestsPerMinute),
P0703|     positiveOrInfinity(options.tokensPerSecond),
P0704|   );
P0705|   const context: ObserveContext = {
P0706|     definition,
P0707|     options,
P0708|     limiter,
P0709|     usage,
P0710|     countedRequestIds: new Set(),
P0711|     client: options.client,
P0712|     clientFailure: undefined,
P0713|     authFailure: false,
P0714|     authStopController,
P0715|   };
P0716|   const observations: Observation[] = new Array(plan.items.length);
P0717|   let next = 0;
P0718|   const workerCount = Math.max(1, Math.min(Math.floor(options.concurrency) || 1, plan.items.length || 1));
P0719| 
P0720|   async function worker(): Promise<void> {
P0721|     for (;;) {
P0722|       const index = next++;
P0723|       const item = plan.items[index];
P0724|       if (!item) return;
P0725|       try {
P0726|         observations[index] = await observeItem(item, context);
P0727|       } catch {
P0728|         // Keep the worker alive and keep failures free of exception/body text.
P0729|         observations[index] = makeUnevaluated(item, "request_failed");
P0730|       }
P0731|     }
P0732|   }
P0733| 
P0734|   try {
P0735|     await Promise.all(Array.from({ length: workerCount }, () => worker()));
