P0001| import { readFile } from "node:fs/promises";
P0002| import { join } from "node:path";
P0003| import { hash } from "../shared/hash.js";
P0004| import type {
P0005|   Answers,
P0006|   AspectDefinition,
P0007|   Json,
P0008|   Plan,
P0009|   PlanItem,
P0010|   PreparedTarget,
P0011|   Question,
P0012|   Questions,
P0013| } from "../types.js";
P0014| 
P0015| /** The limits used by the pinned Jev model.  Estimates are deliberately approximate. */
P0016| export const MAX_INPUT_TOKENS_PER_QUESTION = 32_000;
P0017| export const MAX_INPUT_TOKENS_PER_REQUEST = 64_000;
P0018| 
P0019| /** Cache records are kept under the state directory, one JSON document per answer. */
P0020| export const CACHE_DIRECTORY = "observations";
P0021| export const CACHE_SCHEMA = 1;
P0022| 
P0023| export interface CacheRecord {
P0024|   schema: typeof CACHE_SCHEMA;
P0025|   key: string;
P0026|   model: string;
P0027|   inputHash: string;
P0028|   questionHash: string;
P0029|   answer: Record<string, unknown>;
P0030|   requestId: string;
P0031|   usage?: { inputTokens?: number; outputTokens?: number };
P0032|   observedAt: string;
P0033| }
P0034| 
P0035| /**
P0036|  * Return the exact cache key for one question.  The model is part of the key so
P0037|  * that changing the pinned model never reuses an observation from another model.
P0038|  */
P0039| export function cacheKeyFor(
P0040|   model: string,
P0041|   inputHash: string,
P0042|   question: Question,
P0043| ): string {
P0044|   return hash({ model, inputHash, question });
P0045| }
P0046| 
P0047| export function cachePathFor(stateDir: string, key: string): string {
P0048|   return join(stateDir, CACHE_DIRECTORY, `${key}.json`);
P0049| }
P0050| 
P0051| function isRecord(value: unknown): value is Record<string, unknown> {
P0052|   return typeof value === "object" && value !== null && !Array.isArray(value);
P0053| }
P0054| 
P0055| function finiteNumber(value: unknown): value is number {
P0056|   return typeof value === "number" && Number.isFinite(value);
P0057| }
P0058| 
P0059| function probability(value: unknown): value is number {
P0060|   return finiteNumber(value) && value >= 0 && value <= 1;
P0061| }
P0062| 
P0063| function isProbabilityMap(value: unknown): value is Record<string, number> {
P0064|   return isRecord(value) && Object.values(value).every(probability);
P0065| }
P0066| 
P0067| function questionCriteriaLabels(question: Question): string[] {
P0068|   if (question.type !== "choice" || !isRecord(question.criteria)) return [];
P0069|   return Object.keys(question.criteria);
P0070| }
P0071| 
P0072| function scoreCriteriaCount(question: Question): number | undefined {
P0073|   if (question.type !== "score" || !Array.isArray(question.criteria)) return undefined;
P0074|   return question.criteria.length;
P0075| }
P0076| 
P0077| function hasExpectedProbabilityKeys(
P0078|   probabilities: Record<string, number>,
P0079|   expected: string[],
P0080| ): boolean {
P0081|   const actual = Object.keys(probabilities).sort();
P0082|   const wanted = [...expected].sort();
P0083|   return actual.length === wanted.length && actual.every((key, index) => key === wanted[index]);
P0084| }
P0085| 
P0086| function probabilitiesSumToOne(probabilities: Record<string, number>): boolean {
P0087|   const sum = Object.values(probabilities).reduce((total, value) => total + value, 0);
P0088|   // Each probability is rounded independently; use the same bound as derivation.
P0089|   const roundingTolerance = Math.min(0.02, Object.keys(probabilities).length * 0.005) + 1e-6;
P0090|   return Math.abs(sum - 1) <= roundingTolerance;
P0091| }
P0092| 
P0093| /** Validate the answer shape required before an observation may enter cache. */
P0094| export function isValidAnswer(
P0095|   question: Question,
P0096|   answer: unknown,
P0097| ): answer is Record<string, unknown> {
P0098|   if (!isRecord(answer) || answer.type !== question.type) return false;
P0099| 
P0100|   if (question.type === "noul") {
P0101|     return probability(answer.noul);
P0102|   }
P0103| 
P0104|   if (question.type === "score") {
P0105|     if (!finiteNumber(answer.score) || !probability(answer.confidence)) return false;
P0106|     if (!isRecord(answer.legend) || !isProbabilityMap(answer.probabilities)) return false;
P0107|     if (!probabilitiesSumToOne(answer.probabilities)) return false;
P0108|     const count = scoreCriteriaCount(question);
P0109|     if (count !== undefined) {
P0110|       if (count < 2 || answer.score < 0 || answer.score > count - 1) return false;
P0111|       const expected = Array.from({ length: count }, (_, index) => String(index));
P0112|       if (!hasExpectedProbabilityKeys(answer.probabilities, expected)) return false;
P0113|       if (!hasExpectedProbabilityKeys(answer.legend as Record<string, number>, expected)) return false;
P0114|       if (Object.values(answer.legend).some(value => typeof value !== "string")) return false;
P0115|     }
P0116|     return true;
P0117|   }
P0118| 
P0119|   if (typeof answer.choice !== "string" || answer.choice.length === 0) return false;
P0120|   const labels = questionCriteriaLabels(question);
P0121|   if (labels.length > 0 && !labels.includes(answer.choice)) return false;
P0122|   if (!probability(answer.confidence) || !isProbabilityMap(answer.probabilities)) return false;
P0123|   if (labels.length > 0 && !hasExpectedProbabilityKeys(answer.probabilities, labels)) return false;
P0124|   if (!probabilitiesSumToOne(answer.probabilities)) return false;
P0125|   return true;
P0126| }
P0127| 
P0128| function isValidCacheRecord(
P0129|   value: unknown,
P0130|   key: string,
P0131|   model: string,
P0132|   inputHash: string,
P0133|   question: Question,
P0134| ): value is CacheRecord {
