P0137|   if (value.key !== key) return false;
P0138|   if (value.model !== model || value.inputHash !== inputHash) return false;
P0139|   if (value.questionHash !== hash(question)) return false;
P0140|   if (!isRecord(value.answer) || !isValidAnswer(question, value.answer)) return false;
P0141|   if (typeof value.requestId !== "string" || value.requestId.length === 0) return false;
P0142|   if (typeof value.observedAt !== "string" || value.observedAt.length === 0) return false;
P0143|   if (value.usage !== undefined) {
P0144|     if (!isRecord(value.usage)) return false;
P0145|     for (const keyName of ["inputTokens", "outputTokens"]) {
P0146|       const tokenValue = value.usage[keyName];
P0147|       if (tokenValue !== undefined && (!finiteNumber(tokenValue) || tokenValue < 0)) return false;
P0148|     }
P0149|   }
P0150|   return true;
P0151| }
P0152| 
P0153| /** Read one cache entry without creating a directory or changing any state. */
P0154| export async function readCacheRecord(
P0155|   stateDir: string,
P0156|   key: string,
P0157|   model: string,
P0158|   inputHash: string,
P0159|   question: Question,
P0160| ): Promise<CacheRecord | null> {
P0161|   let text: string;
P0162|   try {
P0163|     text = await readFile(cachePathFor(stateDir, key), "utf8");
P0164|   } catch {
P0165|     return null;
P0166|   }
P0167|   try {
P0168|     const parsed: unknown = JSON.parse(text);
P0169|     if (isValidCacheRecord(parsed, key, model, inputHash, question)) return parsed;
P0170|     // A present but corrupt/mismatched record is a safe miss.
P0171|     return null;
P0172|   } catch {
P0173|     return null;
P0174|   }
P0175| }
P0176| 
P0177| /** A conservative, JSON-size based token estimate used only for planning. */
P0178| export function approximateTokens(value: unknown): number {
P0179|   let serialized: string;
P0180|   try {
P0181|     serialized = JSON.stringify(value);
P0182|   } catch {
P0183|     return Number.POSITIVE_INFINITY;
P0184|   }
P0185|   if (serialized === undefined) return Number.POSITIVE_INFINITY;
P0186|   return Math.ceil(serialized.length / 3);
