P0001| import { stripVTControlCharacters } from "node:util";
P0002| import { hash } from "../shared/hash.js";
P0003| import type { Band, Finding, Run, RunAspect } from "../types.js";
P0004| 
P0005| const bands: Band[] = ["0..0.05", "0.05..0.15", "0.15..0.30", ">=0.30"];
P0006| const text = (value: unknown): string => stripVTControlCharacters(String(value)).replace(/[\u0000-\u001f\u007f]/g, " ");
P0007| const md = (value: unknown): string => text(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/[\\`*_[\]{}|]/g, "\\$&");
P0008| const score = (value: number | null | undefined): string => value == null ? "—" : value.toFixed(3);
P0009| const count = (value: number | null | undefined): string => value == null ? "—" : String(value);
P0010| const deferred = (finding: Finding): boolean => ["accept", "defer", "dismiss"].includes(finding.label?.resolution ?? "");
P0011| 
P0012| function verifiedSnapshot(run: Run, finding: Finding, output: string): Run["snapshots"][string] {
P0013|   const snapshot = run.snapshots[finding.evidence.inputHash];
P0014|   if (!snapshot || hash(snapshot.state) !== finding.evidence.inputHash) throw new Error(`Cannot create ${output}: evaluated snapshot is missing or its hash does not match`);
P0015|   if (!snapshot.questionsHash || hash(snapshot.questions) !== snapshot.questionsHash) throw new Error(`Cannot create ${output}: saved questions hash is missing or does not match; regenerate the run with scan`);
P0016|   return snapshot;
P0017| }
P0018| 
P0019| export function codeFence(value: string, language = ""): string {
P0020|   const longest = Math.max(2, ...[...value.matchAll(/`+/g)].map(m => m[0].length));
P0021|   const fence = "`".repeat(longest + 1);
P0022|   return `${fence}${language}\n${value}\n${fence}`;
P0023| }
P0024| 
P0025| function currentScore(past: RunAspect, current: RunAspect): number | null {
P0026|   if (!past.evaluated) return null;
P0027|   let expected = 0;
P0028|   for (const mode of ["focus", "focusprod"] as const) {
P0029|     const table = current.calibration.byContextMode[mode].table;
P0030|     for (const band of bands) {
P0031|       const n = past.bandsByContextMode[mode][band];
P0032|       if (!n) continue;
P0033|       const p = table[band]?.pValid;
P0034|       if (p == null) return null;
P0035|       expected += n * p;
P0036|     }
P0037|   }
P0038|   const hasCalibration = Object.values(current.calibration.byContextMode).some(c => c.source !== "none");
P0039|   return hasCalibration ? 1 - expected / past.evaluated : null;
P0040| }
P0041| 
P0042| function compatibleHistory(run: Run, history: Run[], aspect: RunAspect): Run[] {
P0043|   return history.filter(h => h.run.id !== run.run.id && h.run.complete && h.run.at <= run.run.at
P0044|     && h.scope.id === run.scope.id && h.scope.repositoryId === run.scope.repositoryId
P0045|     && h.aspects.some(a => a.id === aspect.id && a.condition === aspect.condition))
P0046|     .sort((a, b) => a.run.at.localeCompare(b.run.at)).slice(-10);
P0047| }
