P0054|     `Score: ${score(run.total.score)} · ${run.total.aspects} scored aspect(s) · ${run.run.complete ? "complete" : "INCOMPLETE"}`,
P0055|     `Weights: ${esc(JSON.stringify(run.total.weights))}`,
P0056|     `Scope: ${esc(run.scope.id)} · Run: ${esc(run.run.id)}`, "",
P0057|     "Aspect | Score | Open | New | Resolved | Pending | Evaluated | Calibration | Condition"];
