P1345|   const relativePaths = await enumerateFiles(resolvedRoot, normalizedPaths, errors);
P1346|   const prepared = await prepareFileEntries(resolvedRoot, relativePaths, include, exclude, errors);
P1347|   const sourceHashes: Record<string, string> = {};
P1348|   for (const entry of prepared.entries) if (entry.hash) sourceHashes[entry.relativePath] = entry.hash;
P1349|   if (definition.id === "naming-honesty") {
