P1365|     const tests = testCalls(calls, file.source, describes, diagnostics, parseErrors);
P1366|     if (tests.skipped > 0) diagnostics.push(`skipped tests: ${tests.skipped}`);
P1367|     if (diagnostics.length > 0) diagnosticsByFile.set(file.relativePath, diagnostics);
P1368|     if (tests.records.length === 0) continue;
P1369|     const occurrenceByIdentity = new Map<string, number>();
P1370|     const production = productionModule(file, files);
P1371|     for (const record of tests.records) {
P1372|       const identity = `${record.path.join("\u0000")}\u0001${record.title}`;
P1373|       const occurrence = (occurrenceByIdentity.get(identity) ?? 0) + 1;
P1374|       occurrenceByIdentity.set(identity, occurrence);
P1375|       const sibling = tests.records.find((candidate) => candidate.node.id() !== record.node.id());
P1376|       const ownSnippet = pickSnippet(record.node, file.source);
P1377|       const siblingSnippet = sibling ? pickSnippet(sibling.node, file.source, record.node) : null;
P1378|       let contextMode: ContextMode = production.file ? "focusprod" : "focus";
P1379|       let contextReason = production.reason;
