P1381|       let state = targetState(file.relativePath, record, folded, production.file);
P1382|       let questions = targetQuestions(definition, record, file.source, ownSnippet, siblingSnippet, folded);
P1383|       if (production.file && exceedsInputLimit(state, questions)) {
P1384|         contextMode = "focus";
P1385|         contextReason = "production_context_input_limit";
P1386|         state = targetState(file.relativePath, record, folded, null);
P1387|         questions = targetQuestions(definition, record, file.source, ownSnippet, siblingSnippet, folded);
P1388|       }
P1389|       let unjudgeableReason: string | undefined;
P1390|       if (!targetContextAligned(file.source, folded, record)) {
P1391|         unjudgeableReason = "context_alignment_failed";
P1392|         contextReason = contextReason ?? "context_alignment_failed";
P1393|       }
P1394|       if (exceedsInputLimit(state, questions)) {
P1395|         unjudgeableReason = unjudgeableReason ?? "input_limit";
P1396|         contextReason = contextReason ?? "input_limit";
P1397|       }
P1398|       // Evidence describes the files a reviewer would need to validate the
P1399|       // proposition. It remains complete even when production text is omitted
P1400|       // from the transmitted state because of the input limit.
P1401|       const sources = evidenceSources(file.relativePath, sourceHashes[file.relativePath] ?? hashText(file.rawSource), production.file, sourceHashes);
