P1404|         fingerprint,
P1405|         aspect: definition.id,
P1406|         location: { file: file.relativePath, startLine: record.range.startLine, endLine: record.range.endLine },
P1407|         target: { path: record.path, name: record.title },
P1408|         contextMode,
P1409|         ...(contextReason ? { contextReason } : {}),
P1410|         inputHash: hash(state),
P1411|         subjectRevision: subjectRevision(definition.propositionVersion, sources),
P1412|         evidenceSources: sources,
P1413|         state,
P1414|         questions,
P1415|         controls: {
P1416|           own: ownSnippet ? "available" : "not_available",
P1417|           sibling: siblingSnippet ? "available" : "not_available",
P1418|         },
P1419|         ...(unjudgeableReason ? { unjudgeableReason } : {}),
P1420|       });
P1421|     }
P1422|   }
P1423|   const scopeFiles: ScopeFile[] = prepared.entries.map((entry) => ({
P1424|     file: entry.relativePath,
P1425|     status: entry.status,
P1426|     ...(entry.hash ? { hash: entry.hash } : {}),
P1427|     ...((entry.reason || diagnosticsByFile.has(entry.relativePath)) ? {
