P1432|     repositoryId: repository,
P1433|     id: scopeId(repository, normalizedPaths, include, exclude),
P1434|     paths: normalizedPaths,
P1435|     include,
P1436|     exclude,
P1437|     languages: LANGUAGE_NAMES,
P1438|     selectionPolicy: "files@1",
