P0012| function validCalibrationRow(value: Record<string, unknown>): boolean {
P0013|   const { valid, invalid, prioritized, high, pValid, pHigh } = value;
P0014|   if (!count(valid) || !count(invalid) || !count(prioritized) || !count(high)
P0015|     || !probability(pValid) || !probability(pHigh)
P0016|     || high > prioritized || prioritized > valid) return false;
P0017|   const validityCount = valid + invalid;
P0018|   if (!Number.isSafeInteger(validityCount)) return false;
P0019|   const expectedPValid = validityCount === 0 ? null : valid / validityCount;
P0020|   const expectedPHigh = prioritized === 0 ? null : high / prioritized;
P0021|   return pValid === expectedPValid && pHigh === expectedPHigh;
