L0093| /** Validate the answer shape required before an observation may enter cache. */
L0094| export function isValidAnswer(
L0095|   question: Question,
L0096|   answer: unknown,
L0097| ): answer is Record<string, unknown> {
L0098|   if (!isRecord(answer) || answer.type !== question.type) return false;
L0099| 
L0100|   if (question.type === "noul") {
L0101|     return probability(answer.noul);
L0102|   }
L0103| 
L0104|   if (question.type === "score") {
