        errors.push(`${relativePath}: parse error`);
        continue;
      }
      const parseErrors = parseErrorRanges(file.ast, file.source);
      if (isWholeFileParseFailure(file.ast, file.source, parseErrors)) {
        entry.status = "error";
        entry.reason = "parse_error";
        entries.push(entry);
        complete = false;
        errors.push(`${relativePath}: parse error`);
        continue;
      }
      entry.status = "parsed";
      if (parseErrors.length > 0) {
        entry.reason = `parse_diagnostic (${parseErrors.length} parser error${parseErrors.length === 1 ? "" : "s"})`;
      }
      entry.rawSource = file.rawSource;
      entry.source = file.source;
      entry.ast = file.ast;
      entries.push(entry);
      parsed.push({ ...file, parseErrors });
    } catch (error) {
      entry.status = "error";
      entry.reason = "parse_error";
      entries.push(entry);
      complete = false;
      errors.push(`${relativePath}: parse error (${error instanceof Error ? error.message : String(error)})`);
    }
  }
  return { entries, parsed, complete };
}

async function prepareFileEntries(
  root: string,
  relativePaths: string[],
  include: string[],
  exclude: string[],
  errors: string[],
): Promise<{ entries: FileEntry[]; parsed: ParsedFile[]; complete: boolean }> {
  const entries: FileEntry[] = [];
  const parsed: ParsedFile[] = [];
  let complete = true;
  for (const relativePath of relativePaths) {
    const absolutePath = path.resolve(root, relativePath);
    const entry: FileEntry = { relativePath, absolutePath, status: "skipped" };
    const extension = path.extname(relativePath).toLowerCase();
    if (!SOURCE_EXTENSIONS.has(extension)) {
      entry.reason = "unsupported_file";
      entries.push(entry);
      continue;
    }
    if (!matchesAny(relativePath, include)) {
      entry.reason = "not_included";
      entries.push(entry);
      continue;
    }
    if (matchesAny(relativePath, exclude)) {
      entry.reason = "excluded";
      entries.push(entry);
      continue;
    }
    let rawSource: string;
    try {
      rawSource = await fs.readFile(absolutePath, "utf8");
    } catch (error) {
      entry.status = "error";
      entry.reason = "read_error";
      entries.push(entry);
      complete = false;
      errors.push(`${relativePath}: cannot read source (${error instanceof Error ? error.message : String(error)})`);
      continue;
    }
    entry.hash = hashText(rawSource);
    try {
      const file = parseFile(relativePath, rawSource);
      if (file.ast.kind() === "ERROR") {
        entry.status = "error";
        entry.reason = "parse_error";
        entries.push(entry);
        complete = false;
        errors.push(`${relativePath}: parse error`);
        continue;
      }
      const parseErrors = parseErrorRanges(file.ast, file.source);
      if (isWholeFileParseFailure(file.ast, file.source, parseErrors)) {
        entry.status = "error";
        entry.reason = "parse_error";
        entries.push(entry);
        complete = false;
        errors.push(`${relativePath}: parse error`);
        continue;
      }
      entry.status = "parsed";
      if (parseErrors.length > 0) {
        entry.reason = `parse_diagnostic (${parseErrors.length} parser error${parseErrors.length === 1 ? "" : "s"})`;
      }
      entry.rawSource = file.rawSource;
      entry.source = file.source;
      entry.ast = file.ast;
      entries.push(entry);
      parsed.push({ ...file, parseErrors });
    } catch (error) {
      entry.status = "error";
      entry.reason = "parse_error";
      entries.push(entry);
      complete = false;
      errors.push(`${relativePath}: parse error (${error instanceof Error ? error.message : String(error)})`);
    }
  }
  return { entries, parsed, complete };
}

